import json
b = json.loads(open('baseline-packages.json','rb').read().decode('utf-8-sig'))
a = json.loads(open('after-cpm-packages.json','rb').read().decode('utf-8-sig'))
# Compare resolved versions per project
def get_pkgs(data):
    result = {}
    for proj in data.get('projects', []):
        name = proj['path'].split('/')[-1]
        pkgs = {}
        for fw in proj.get('frameworks', []):
            for p in fw.get('topLevelPackages', []):
                pkgs[p['id']] = p['resolvedVersion']
        result[name] = pkgs
    return result
bp = get_pkgs(b)
ap = get_pkgs(a)
if bp == ap:
    print('MATCH: All resolved versions identical')
else:
    print('DIFF:')
    for proj in sorted(set(list(bp.keys()) + list(ap.keys()))):
        for pkg in sorted(set(list(bp.get(proj,{}).keys()) + list(ap.get(proj,{}).keys()))):
            bv = bp.get(proj,{}).get(pkg,'MISSING')
            av = ap.get(proj,{}).get(pkg,'MISSING')
            if bv != av:
                print(f'  {proj}/{pkg}: {bv} -> {av}')
"

